$files = Get-ChildItem -Path . -Filter *.html; foreach ($f in $files) { $content = Get-Content $f.FullName -Raw; if ($content -notmatch "<link rel=""icon""") { $content = $content -replace "</head>", "`r`n    <link rel=""icon"" href=""data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>?</text></svg>"">`r`n</head>"; Set-Content -Path $f.FullName -Value $content } }
